use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The node's entire network authority, mirrored from its `with` clause.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extract the host from an http(s) URL. Returns `None` for anything that is
/// not a plain http(s) URL with a host: userinfo, whitespace, control characters
/// and backslashes are all rejected outright.
fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let end = rest
        .find(|c: char| matches!(c, '/' | '?' | '#'))
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty()
        || authority
            .chars()
            .any(|c| c == '@' || c == '\\' || c.is_whitespace() || c.is_control())
    {
        return None;
    }
    let host = match authority.rfind(':') {
        Some(i) => &authority[..i],
        None => authority,
    };
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn is_allowed(host: &str) -> bool {
    ALLOWED_HOSTS.iter().any(|a| a.eq_ignore_ascii_case(host))
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            // Refuse out-of-scope URLs here as data, so one bad entry in an
            // untrusted list cannot trap the whole node at the boundary.
            match host_of(&url) {
                Some(host) if is_allowed(host) => {}
                _ => {
                    failures.push(FetchFailure {
                        url,
                        error: "url malformed or host not in allowlist".to_string(),
                    });
                    continue;
                }
            }

            // `fetch` returns transport failures (timeout, error status, size
            // cap) as values, so one dead feed does not fail the run.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
